# Analyze each changed pair
changed = [(0, 'gkhdw', 'gkcdw'), (1, 'eewcb', 'eewvjif'), (4, 'xuw', 'xfuaw')]

for idx, inp, outp in changed:
    print(f"Input: '{inp}' -> Output: '{outp}'")

    # Find differences character by character
    diff_positions = []
    for i, (char_in, char_out) in enumerate(zip(inp, outp)):
        if char_in != char_out:
            diff_positions.append((i, char_in, char_out))

    # Handle cases where lengths differ
    if len(inp) != len(outp):
        if len(inp) > len(outp):
            # Removal case
            for i in range(len(outp)):
                if inp[i] != outp[i]:
                    diff_positions.append((i, inp[i], 'DEL'))
            # Add remaining chars from input
            for i in range(len(outp), len(inp)):
                diff_positions.append((i, inp[i], 'DEL'))
        else:
            # Addition case  
            for i in range(len(inp)):
                if inp[i] != outp[i]:
                    diff_positions.append((i, 'ADD', outp[i]))
            # Add remaining chars from output
            for i in range(len(inp), len(outp)):
                diff_positions.append((i, 'ADD', outp[i]))

    print(f"  Differences: {diff_positions}")
    print()

